];
const r=await Promise.all(urls.map(url=>tools.browser_render({url})));
function clean(s){return (s||'').replace(/\s+/g,' ').trim()}
function bodyStart(text,title){
  let t=clean(text);
  if(title && t.startsWith(title)) t=clean(t.slice(title.length));
  return t ? [...t].slice(0,120).join('') : '';
}
return r.map((x,i)=>({
  url:urls[i],
  title:clean(x.title)||'',
  excerpt:bodyStart(x.content||x.text||x.body||'',clean(x.title)||'')
}));

